<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ArrowLeft, CalendarDays, CheckCircle2, Clock3 } from '@lucide/vue';
import { Button } from '@/components/ui/button';
type Item = { id:number; member_name:string|null; member_email:string|null; trainer_name:string|null; package_name:string|null; facility_name:string|null; start_date:string|null; expires_at:string|null; total_sessions:number; used_sessions:number; remaining_sessions:number; status:string };
type Schedule = { id:number; date:string; start_time:string; end_time:string; member_attended:boolean; trainer_attended:boolean; status:string };
const props = defineProps<{ item:Item; schedules:Schedule[] }>();
const form = useForm({ session_date:'', start_time:'09:00', end_time:'10:00' });
function submit(){ form.post('/membership-trainers/'+props.item.id+'/schedules',{onSuccess:()=>form.reset('session_date')}); }
function formatDate(value:string|null){ return value ? new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(value)) : '—'; }
</script>
<template>
<Head :title="'Detail Paket Trainer · '+(item.member_name || 'Member')" />
<div class="space-y-6 p-4 md:p-6">
<div class="flex items-center gap-3"><Button variant="ghost" size="icon" as-child><Link href="/membership-trainers"><ArrowLeft class="size-4"/></Link></Button><div><p class="text-sm text-muted-foreground">Membership Trainer / Detail</p><h1 class="text-xl font-semibold">Detail Paket Trainer</h1></div></div>
<section class="rounded-2xl border bg-card p-5 shadow-sm md:p-6">
<div class="flex flex-col justify-between gap-4 md:flex-row md:items-start"><div><p class="text-sm text-muted-foreground">Member</p><h2 class="mt-1 text-2xl font-semibold">{{item.member_name || '—'}}</h2><p class="mt-1 text-sm text-muted-foreground">{{item.member_email || '—'}}</p></div><span class="w-fit rounded-full bg-emerald-500/10 px-3 py-1.5 text-xs font-semibold text-emerald-700">{{item.status}}</span></div>
<div class="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><div><p class="text-xs text-muted-foreground">Trainer</p><p class="mt-1 font-medium">{{item.trainer_name || '—'}}</p></div><div><p class="text-xs text-muted-foreground">Paket</p><p class="mt-1 font-medium">{{item.package_name || '—'}}</p></div><div><p class="text-xs text-muted-foreground">Olahraga</p><p class="mt-1 font-medium">{{item.facility_name || '—'}}</p></div><div><p class="text-xs text-muted-foreground">Periode</p><p class="mt-1 font-medium">{{formatDate(item.start_date)}} – {{formatDate(item.expires_at)}}</p></div></div>
<div class="mt-6 grid gap-3 sm:grid-cols-3"><div class="rounded-xl bg-muted/50 p-4"><p class="text-xs text-muted-foreground">Total sesi</p><p class="mt-1 text-2xl font-semibold">{{item.total_sessions}}</p></div><div class="rounded-xl bg-muted/50 p-4"><p class="text-xs text-muted-foreground">Sesi terpakai</p><p class="mt-1 text-2xl font-semibold">{{item.used_sessions}}</p></div><div class="rounded-xl bg-primary/5 p-4"><p class="text-xs text-muted-foreground">Sisa sesi</p><p class="mt-1 text-2xl font-semibold text-primary">{{item.remaining_sessions}}</p></div></div>
</section>
<div class="grid gap-6 xl:grid-cols-[.8fr_1.2fr]">
<section class="h-fit rounded-2xl border bg-card p-5 shadow-sm"><div class="flex items-center gap-2"><CalendarDays class="size-5 text-primary"/><h2 class="font-semibold">Tambah jadwal sesi</h2></div><p class="mt-1 text-sm text-muted-foreground">Jadwal otomatis terhubung ke paket {{item.package_name}} milik {{item.member_name}}.</p>
<form class="mt-5 space-y-4" @submit.prevent="submit"><div class="space-y-1.5"><label class="text-sm font-medium">Tanggal sesi</label><input v-model="form.session_date" type="date" required :min="item.start_date || undefined" :max="item.expires_at || undefined" class="w-full rounded-md border bg-background px-3 py-2 text-sm"/><p v-if="form.errors.session_date" class="text-xs text-destructive">{{form.errors.session_date}}</p></div>
<div class="grid grid-cols-2 gap-3"><div class="space-y-1.5"><label class="text-sm font-medium">Mulai</label><input v-model="form.start_time" type="time" required class="w-full rounded-md border bg-background px-3 py-2 text-sm"/></div><div class="space-y-1.5"><label class="text-sm font-medium">Selesai</label><input v-model="form.end_time" type="time" required class="w-full rounded-md border bg-background px-3 py-2 text-sm"/></div></div><p v-if="form.errors.start_time || form.errors.end_time" class="text-xs text-destructive">{{form.errors.start_time || form.errors.end_time}}</p>
<Button type="submit" class="w-full" :disabled="form.processing || item.remaining_sessions < 1"><Clock3 class="mr-2 size-4"/>Simpan jadwal</Button><p v-if="item.remaining_sessions < 1" class="text-xs text-destructive">Kuota sesi paket ini sudah habis.</p></form></section>
<section class="overflow-hidden rounded-2xl border bg-card shadow-sm"><div class="border-b px-5 py-4"><h2 class="font-semibold">Riwayat jadwal sesi</h2><p class="mt-1 text-xs text-muted-foreground">Kuota berkurang setelah member dan trainer sama-sama mengonfirmasi kehadiran setelah sesi berakhir.</p></div>
<div v-if="schedules.length" class="divide-y"><article v-for="schedule in schedules" :key="schedule.id" class="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p class="font-medium">{{formatDate(schedule.date)}}</p><p class="mt-1 text-sm text-muted-foreground">{{schedule.start_time}}–{{schedule.end_time}}</p></div><div class="flex flex-wrap gap-2 text-xs"><span class="rounded-full px-2.5 py-1" :class="schedule.member_attended ? 'bg-emerald-500/10 text-emerald-700' : 'bg-muted text-muted-foreground'">Member {{schedule.member_attended ? 'hadir' : 'belum'}}</span><span class="rounded-full px-2.5 py-1" :class="schedule.trainer_attended ? 'bg-emerald-500/10 text-emerald-700' : 'bg-muted text-muted-foreground'">Trainer {{schedule.trainer_attended ? 'hadir' : 'belum'}}</span><span class="rounded-full bg-muted px-2.5 py-1">{{schedule.status === 'completed' ? 'Selesai' : 'Terjadwal'}}</span></div></article></div>
<div v-else class="p-10 text-center text-sm text-muted-foreground"><CheckCircle2 class="mx-auto mb-2 size-8 opacity-40"/>Belum ada jadwal sesi untuk paket ini.</div></section>
</div></div>
</template>